configuration.jsScript:
// Compute derived vibration features from raw telemetry payload.
// Input fields: peak_g (array or scalar), rms (optional pre-computed), temperature, rpm
// Output: enriched message with rms_mms, crest_factor, kurtosis, iso_zone

var rms_mms = msg.rms !== undefined ? msg.rms : 0.0;
var peak    = msg.peak_g !== undefined ? Math.abs(msg.peak_g) : 0.0;
var kurt    = msg.kurtosis !== undefined ? msg.kurtosis : 0.0;
var temp_c  = msg.temperature !== undefined ? msg.temperature : 0.0;
var rpm     = msg.rpm !== undefined ? msg.rpm : 0.0;

// Crest Factor = peak / RMS  (values >6 indicate impulsive fault)
var crest_factor = rms_mms > 0 ? (peak / rms_mms) : 0.0;

// ISO 10816-3 severity zones for machines 15–300 kW:
//   Zone A: rms <= 2.3  mm/s  (new or just repaired)
//   Zone B: rms <= 4.5  mm/s  (acceptable for long-term operation)
//   Zone C: rms <= 11.2 mm/s  (alarm — investigate soon)
//   Zone D: rms >  11.2 mm/s  (danger — shut down)
var iso_zone;
if      (rms_mms <= 2.3)  { iso_zone = 'A'; }
else if (rms_mms <= 4.5)  { iso_zone = 'B'; }
else if (rms_mms <= 11.2) { iso_zone = 'C'; }
else                      { iso_zone = 'D'; }

// Health score 0–100 (linear interpolation across zones)
var health_score = Math.max(0, Math.min(100, 100 - (rms_mms / 11.2) * 70));

msg.rms_mms       = parseFloat(rms_mms.toFixed(3));
msg.crest_factor  = parseFloat(crest_factor.toFixed(3));
msg.kurtosis      = parseFloat(kurt.toFixed(3));
msg.iso_zone      = iso_zone;
msg.health_score  = parseFloat(health_score.toFixed(1));
msg.temperature   = temp_c;
msg.rpm           = rpm;
msg.bpfo_magnitude = msg.bpfo_magnitude !== undefined ? msg.bpfo_magnitude : 0.0;

return {msg: msg, metadata: metadata, msgType: msgType};

// WARNING: Zone C entry — rms > 4.5 mm/s (ISO 10816 Zone B/C boundary)
if (msg.rms_mms > 4.5 && msg.rms_mms <= 7.1) { return 'True'; }
return 'False';

// MAJOR: Mid Zone C — rms > 7.1 mm/s
if (msg.rms_mms > 7.1 && msg.rms_mms <= 11.2) { return 'True'; }
return 'False';

// CRITICAL: Zone D — rms > 11.2 mm/s OR kurtosis > 8 (impulsive bearing fault)
if (msg.rms_mms > 11.2 || msg.kurtosis > 8.0) { return 'True'; }
return 'False';

configuration.alarmDetailsBuildJs:
var details = {};
details.rms_mms       = msg.rms_mms;
details.crest_factor  = msg.crest_factor;
details.kurtosis      = msg.kurtosis;
details.iso_zone      = msg.iso_zone;
details.health_score  = msg.health_score;
details.rpm           = msg.rpm;
details.temperature   = msg.temperature;
details.threshold_mms = 4.5;
details.iso_standard  = 'ISO 10816-3 Zone B/C boundary';
details.stage         = 1;
details.action        = 'Inspect at next scheduled maintenance';
return details;

var details = {};
details.rms_mms       = msg.rms_mms;
details.crest_factor  = msg.crest_factor;
details.kurtosis      = msg.kurtosis;
details.iso_zone      = msg.iso_zone;
details.health_score  = msg.health_score;
details.rpm           = msg.rpm;
details.temperature   = msg.temperature;
details.threshold_mms = 7.1;
details.iso_standard  = 'ISO 10816-3 Zone C (mid)';
details.stage         = 2;
details.action        = 'Schedule corrective maintenance within 2 weeks';
return details;

var details = {};
details.rms_mms       = msg.rms_mms;
details.crest_factor  = msg.crest_factor;
details.kurtosis      = msg.kurtosis;
details.iso_zone      = msg.iso_zone;
details.health_score  = msg.health_score;
details.rpm           = msg.rpm;
details.temperature   = msg.temperature;
details.bpfo_magnitude= msg.bpfo_magnitude;
details.threshold_mms = 11.2;
details.iso_standard  = 'ISO 10816-3 Zone D';
details.stage         = '3-4';
details.action        = 'Immediate inspection. Consider emergency shutdown.';
return details;

configuration.bodyTemplate:
A ${metadata.alarmSeverity} vibration alarm was triggered.

Device: ${metadata.deviceName}
Timestamp: ${metadata.ts}
RMS velocity: ${msg.rms_mms} mm/s  (ISO 10816 Zone ${msg.iso_zone})
Crest factor: ${msg.crest_factor}
Kurtosis: ${msg.kurtosis}
Health score: ${msg.health_score}/100

Recommended action: ${metadata.alarm_action}

Open ThingsBoard: http://thingsboard:8080
